contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with one parameter so property ranges over inputs
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // dummy is unused except to satisfy the requirement of at least one parameter
        // Record observable balances before calling refund
        uint256 cBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;

        // If reverted: no observable balance change. If succeeded: c's balance does not increase,
        // this contract's balance increases by at most cBalanceBefore, and no new Ether is created in c.
        assert(
            reverted
            ? (cBalanceAfter == cBalanceBefore && selfBalanceAfter == selfBalanceBefore)
            : (cBalanceAfter <= cBalanceBefore && selfBalanceAfter >= selfBalanceBefore && (selfBalanceAfter - selfBalanceBefore) <= cBalanceBefore)
        );
    }

    receive() external payable {}
}

