// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 cBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;
        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 cBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;
        assertTrue(reverted
            ? (cBalanceAfter == cBalanceBefore && selfBalanceAfter == selfBalanceBefore)
            : (cBalanceAfter <= cBalanceBefore && selfBalanceAfter >= selfBalanceBefore && (selfBalanceAfter - selfBalanceBefore) <= cBalanceBefore));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
